    constructor(C _c) { c = _c; }

    // We will take an ETH amount to forward when calling c.go().
    // The contract must hold at least that amount to send it.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        // Observe owner and balance before the call
        address ownerBefore = c.owner();
        uint256 balBefore = address(c).balance;

        // Perform the call and record whether it reverted
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe owner and balance after the call
        address ownerAfter = c.owner();
        uint256 balAfter = address(c).balance;

        // General invariant: c.owner is never changed by go(), and c's balance does not increase as a result of the call.
        // (Either the call reverted, or owner stayed the same and balance did not grow.)
        assert(reverted || (ownerAfter == ownerBefore && balAfter <= balBefore));
    }

    // allow receiving ETH when the tested contract forwards to this test contract's address
    receive() external payable { }
}

