contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to provide an amount to forward to c.go
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        // Record pre-call observable values
        address ownerBefore = c.owner();
        uint256 balBefore = address(c).balance;

        // Make the state-changing call on c; capture whether it reverted
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-call observable values
        address ownerAfter = c.owner();
        uint256 balAfter = address(c).balance;

        // General rule:
        // - c.owner must never change (sanity) AND
        // - If the call did not revert then c's balance must be 0 (any funds are forwarded or returned to owner)
        // - If the call reverted then c's balance must be unchanged from before the call
        assert(ownerBefore == ownerAfter && (!reverted ? balAfter == 0 : balAfter == balBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tests a single call that may send Ether
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // observe before-values
        address owner_before = c.owner();
        uint256 balance_before = address(c).balance;

        bool reverted;
        // perform the state-changing call on c as top-level statement
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        address owner_after = c.owner();
        uint256 balance_after = address(c).balance;

        // General rule:
        // 1) owner never changes
        // 2) c's balance never increases above balance_before + amount
        // 3) if the call did not revert then c.balance == 0 (funds forwarded and remaining drained)
        assert(owner_after == owner_before && balance_after <= balance_before + amount && (reverted || balance_after == 0));
    }

    receive() external payable {}
}
